// Map uniform random numbers to [-1,1]^2
std::float_t ux = 2.0f * u[0] - 1.0f;
std::float_t uy = 2.0f * u[1] - 1.0f;

// Reject samples outside the unit disk
if (ux * ux + uy * uy > 1.0f) {
    return Vector3f(0, 0, 0); // Invalid sample, caller should retry
}

// Project disk sample to hemisphere
std::float_t r = std::sqrt(std::max(0.0f, 1.0f - ux * ux - uy * uy));
return Vector3f(ux, uy, r);

// END_CODE

